// RNG, seed value
// random utilites
uint seed = 0u;
uint wangHash () {
	seed = uint( seed ^ uint( 61 ) ) ^ uint( seed >> uint( 16 ) );
	seed *= uint( 9 );
	seed = seed ^ ( seed >> 4 );
	seed *= uint( 0x27d4eb2d );
	seed = seed ^ ( seed >> 15 );
	return seed;
}

float NormalizedRandomFloat () {
	return float( wangHash() ) / 4294967296.0f;
}

// remapping functions from https://www.shadertoy.com/view/X3KcDD
// ellipse with major and minor radius
#define PI 3.1415926
vec2 randEllipse(float rx, float ry, float rand1, float rand2) {
    float u = 2.0*PI*rand1;  // θ
    float v = sqrt(rand2);  // r
    vec2 circ = v * vec2(cos(u), sin(u));  // unit circle
    return vec2(rx, ry) * circ;  // linear transform
}

vec2 GetOffset() {
    return randEllipse( 1.2f, 0.8f, NormalizedRandomFloat(), NormalizedRandomFloat() );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    // initial point position
    vec2 uv = fragCoord / iResolution.xy;

    // seeding the RNG
    seed = uint( 42069.0f * fragCoord.x + 69420.0f * fragCoord.y + 666.0f * iTime );

    // sample the b/w texture for kernel diameter
    float bokehSize = texture( iChannel1, uv ).r * 0.125f;

    // loop over jittered samples
    const int numSamples = 30;
    vec3 col = vec3( 0.0f );
    for ( int i = 0; i < numSamples; i++ ) {
        col += texture( iChannel0, uv + bokehSize * GetOffset() ).rgb / float( numSamples );
    }

    fragColor = vec4( col, 1.0f );
}
